 void VerifyWarriorTcp(string folder){if(!VerificationRun.Network)return;LeaveLan();ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);var guest=new PanelWindow(true){ShowInTaskbar=false,Opacity=0};guest.Show();try{lanPort.Text=FreeLanPort().ToString();lanDeck.SelectedIndex=0;lanClass.SelectedItem=Classes.First(c=>c.Key=="WARRIOR");BeginLan(true);guest.lanDeck.SelectedIndex=0;guest.lanClass.SelectedItem=Classes.First(c=>c.Key=="WARRIOR");guest.lanAddress.Text="127.0.0.1:"+lanPort.Text;guest.BeginLan(false);PumpLan(()=>lanReady&&guest.lanReady,"Warrior TCP peers connect");DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>guest.match.Players[0].MulliganDone,"Host mulligan reaches guest");guest.DoMatch("mulligan",selectedIds:new int[0]);PumpLan(()=>match.MulliganComplete&&!guest.lanWaiting,"Both Warrior mulligans complete");var g=lanAuthority.Game;foreach(var p in g.Players){p.Hand.Clear();p.Board.Clear();p.Mana=10;}var smith=g.Summon(0,"VAN_EX1_402");var frothing=g.Summon(0,"VAN_EX1_604");g.Summon(1,"VAN_CS2_182");int whirl=Inject(g,"EX1_400");PublishLan();PumpLan(()=>guest.match.Players[0].Board.Count==2,"Warrior fixture reaches guest");DoMatch("play",whirl);PumpLan(()=>guest.match.Players[0].Armor==2,"Armorsmith armor reaches TCP guest");Check(guest.match.AttackValue(guest.match.Players[0].Board.Single(u=>u.Id==frothing.Id))==5&&guest.match.Players[0].Hand.Count==0,"Frothing attack synchronizes without leaking hand");int shout=Inject(g,"NEW1_036");DoMatch("play",shout);PumpLan(()=>guest.match.Players[0].CommandingShoutTurn==g.Turn,"Shout duration synchronizes");Check(guest.match.Players[0].Board.All(u=>u.CommandingShoutTurn==g.Turn),"Shout enchantments synchronize");ApplyTheme(true,true);ApplyMode(false);SetFullEffects(false);RenderMatch();ShowPage("match");Render(Path.Combine(folder,"122-warrior-codex.png"));ApplyMode(true);Render(Path.Combine(folder,"123-warrior-minimal.png"));Check(Width==392&&Height==300,"Warrior retains compact minimal dimensions");CheckNormalWeights(this);
  }finally{guest.LeaveLan();guest.Close();LeaveLan();}}
